; The Rust hooks' NASM entries (generated by hooks_026g.py from the patches' <patch>.toml: do not edit).
; Each entry (RUST_CALL, rust_hook_026g.inc) presents a site's arguments to
; its shim and cleans up as the game's function did. The arena's block
; patches.code (with the crate); link_026g.py installs each site.
bits 32
section .text
%include "rust_hook_026g.inc"

; 0x1f7c3c game_world::tick's join after the simulation's move (cmp byte [esp+0Fh],0; EBX the game world): lohook -> ragdoll_on_step
global ragdoll_on_step
extern hook_ragdoll_on_step
ragdoll_on_step:
    lea esp, [esp - 4]
    pushfd
    pushad
    cld
    mov ebp, esp
    sub esp, 512
    and esp, -16
    fxsave [esp]
    mov edi, esp
    sub esp, 8
    and esp, -16
    mov [esp], ebp
    mov [esp+4], edi
    mov eax, esp
    sub esp, 12
    push eax
    call hook_ragdoll_on_step
    mov edx, ragdoll_on_step_replay
    cmp eax, 0
    je ragdoll_on_step_go
    mov edx, 0x1f7c41
    cmp eax, 1
    je ragdoll_on_step_go
    ud2
ragdoll_on_step_go:
    mov [ebp + 36], edx
    fxrstor [edi]
    mov esp, ebp
    popad
    popfd
    ret
ragdoll_on_step_replay:
    db 0x80, 0x7c, 0x24, 0x0f, 0x00
    jmp 0x1f7c41

